import React, { useEffect, useState } from 'react';
import { itemsAPI, formatCurrency } from '../api';

function Items({ showToast }) {
  const [items, setItems] = useState([]);
  const [filteredItems, setFilteredItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    category: '',
    price: '',
    quantity: '',
    sku: '',
  });

  useEffect(() => {
    loadItems();
  }, []);

  useEffect(() => {
    const filtered = items.filter(
      (item) =>
        item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.category?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.sku.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredItems(filtered);
  }, [searchTerm, items]);

  const loadItems = async () => {
    try {
      setLoading(true);
      const data = await itemsAPI.getAll();
      setItems(data.data || []);
    } catch (error) {
      showToast(`Failed to load items: ${error.message}`, 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingItem) {
        await itemsAPI.update(editingItem._id, formData);
        showToast('Item updated successfully!');
      } else {
        await itemsAPI.create(formData);
        showToast('Item added successfully!');
      }
      resetForm();
      loadItems();
    } catch (error) {
      showToast(`Operation failed: ${error.message}`, 'error');
    }
  };

  const handleEdit = (item) => {
    setEditingItem(item);
    setFormData({
      name: item.name,
      description: item.description || '',
      category: item.category || '',
      price: item.price,
      quantity: item.quantity,
      sku: item.sku,
    });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this item?')) return;
    
    try {
      await itemsAPI.delete(id);
      showToast('Item deleted successfully!');
      loadItems();
    } catch (error) {
      showToast(`Failed to delete item: ${error.message}`, 'error');
    }
  };

  const resetForm = () => {
    setFormData({
      name: '',
      description: '',
      category: '',
      price: '',
      quantity: '',
      sku: '',
    });
    setEditingItem(null);
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  return (
    <div className="container">
      <div className="section-header">
        <h1 className="section-title">Item Management</h1>
      </div>

      {/* Form */}
      <div className="form-card">
        <h2 className="form-title">{editingItem ? '✏️ Edit Item' : '➕ Add New Item'}</h2>
        <form onSubmit={handleSubmit}>
          <div className="form-grid">
            <div className="form-group">
              <label className="form-label">Item Name *</label>
              <input
                type="text"
                name="name"
                className="form-input"
                value={formData.name}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label">SKU</label>
              <input
                type="text"
                name="sku"
                className="form-input"
                value={formData.sku}
                onChange={handleChange}
                placeholder="Auto-generated if empty"
              />
            </div>

            <div className="form-group">
              <label className="form-label">Category</label>
              <input
                type="text"
                name="category"
                className="form-input"
                value={formData.category}
                onChange={handleChange}
                placeholder="e.g., Electronics"
              />
            </div>

            <div className="form-group">
              <label className="form-label">Price *</label>
              <input
                type="number"
                name="price"
                className="form-input"
                value={formData.price}
                onChange={handleChange}
                step="0.01"
                min="0"
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label">Quantity *</label>
              <input
                type="number"
                name="quantity"
                className="form-input"
                value={formData.quantity}
                onChange={handleChange}
                min="0"
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">Description</label>
            <textarea
              name="description"
              className="form-textarea"
              value={formData.description}
              onChange={handleChange}
            />
          </div>

          <div className="form-actions">
            <button type="submit" className="btn btn-primary">
              {editingItem ? '💾 Update Item' : '➕ Add Item'}
            </button>
            {editingItem && (
              <button type="button" className="btn btn-secondary" onClick={resetForm}>
                ❌ Cancel
              </button>
            )}
          </div>
        </form>
      </div>

      {/* Search */}
      <div className="search-box">
        <span className="search-icon">🔍</span>
        <input
          type="text"
          className="search-input"
          placeholder="Search items by name, category, or SKU..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Items Grid */}
      {loading ? (
        <div className="loading-container">
          <div className="loading-spinner"></div>
          <p className="loading-text">Loading items...</p>
        </div>
      ) : filteredItems.length === 0 ? (
        <div className="empty-state card">
          <div className="empty-state-icon">📦</div>
          <h3 className="empty-state-title">No items found</h3>
          <p className="empty-state-description">
            {searchTerm ? 'Try adjusting your search terms' : 'Add your first item to get started!'}
          </p>
        </div>
      ) : (
        <div className="items-grid">
          {filteredItems.map((item) => (
            <div key={item._id} className="item-card">
              <div className="item-header">
                <h3 className="item-name">{item.name}</h3>
                <div className="item-meta">
                  <span className="badge badge-primary">{item.sku}</span>
                  {item.category && (
                    <span className="badge badge-success">{item.category}</span>
                  )}
                </div>
              </div>

              {item.description && (
                <p className="item-description">{item.description}</p>
              )}

              <div className="item-details">
                <div className="item-detail">
                  <span className="item-detail-value">{formatCurrency(item.price)}</span>
                  <span className="item-detail-label">Price</span>
                </div>
                <div className="item-detail">
                  <span className="item-detail-value">{item.quantity}</span>
                  <span className="item-detail-label">Stock</span>
                </div>
              </div>

              <div className="item-actions">
                <button className="btn btn-primary btn-sm" onClick={() => handleEdit(item)}>
                  ✏️ Edit
                </button>
                <button className="btn btn-danger btn-sm" onClick={() => handleDelete(item._id)}>
                  🗑️ Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default Items;
